import{_ as l,a0 as p,w as r,s as o,ao as d,I as t,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 18.04 服务器上安装和配置 KVM | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 18.04 服务器上安装和配置 KVM | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 18.04 服务器上安装和配置 KVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 18.04 服务器上安装和配置 KVM | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180521 How to Install and Configure KVM on Ubuntu 18.04 LTS Server","title":"如何在 Ubuntu 18.04 服务器上安装和配置 KVM","tag":"201806","desc":""},"relativePath":"201806/20180521 How to Install and Configure KVM on Ubuntu 18.04 LTS Server.md","filePath":"[post].md"}'),u={name:"201806/20180521 How to Install and Configure KVM on Ubuntu 18.04 LTS Server.md"};function c(h,s,g,b,k,m){const n=p("Link");return r(),o("div",null,[s[18]||(s[18]=d(`<h1 id="如何在-ubuntu-18-04-服务器上安装和配置-kvm" tabindex="-1">如何在 Ubuntu 18.04 服务器上安装和配置 KVM <a class="header-anchor" href="#如何在-ubuntu-18-04-服务器上安装和配置-kvm" aria-label="Permalink to “如何在 Ubuntu 18.04 服务器上安装和配置 KVM”">​</a></h1><p><strong>KVM</strong>（基于内核的虚拟机）是一款为类 Linux 系统提供的开源的全虚拟化解决方案，KVM 使用虚拟化扩展（如 <strong>Intel VT</strong> 或 <strong>AMD-V</strong>）提供虚拟化功能。无论何时我们在任何 Linux 机器上安装 KVM，都会通过加载诸如 <code>kvm-intel.ko</code>（基于 Intel 的机器）和 <code>kvm-amd.ko</code>（基于 amd 的机器）的内核模块，使其成为<ruby>管理程序<rt>hyervisor</rt></ruby>（LCTT 译注：一种监控和管理虚拟机运行的核心软件层）。</p><p>KVM 允许我们安装和运行多个虚拟机（Windows 和 Linux）。我们可以通过 <code>virt-manager</code> 的图形用户界面或使用 <code>virt-install</code> 和 <code>virsh</code> 命令在命令行界面来创建和管理基于 KVM 的虚拟机。</p><p>在本文中，我们将讨论如何在 Ubuntu 18.04 LTS 服务器上安装和配置 <strong>KVM 管理程序</strong>。我假设你已经在你的服务器上安装了 Ubuntu 18.04 LTS 。接下来登录到您的服务器执行以下步骤。</p><h3 id="第一步-确认您的硬件是否支持虚拟化" tabindex="-1">第一步：确认您的硬件是否支持虚拟化 <a class="header-anchor" href="#第一步-确认您的硬件是否支持虚拟化" aria-label="Permalink to “第一步：确认您的硬件是否支持虚拟化”">​</a></h3><p>执行 <code>egrep</code> 命令以验证您的服务器的硬件是否支持虚拟化，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ egrep -c &#39;(vmx|svm)&#39; /proc/cpuinfo</span></span>
<span class="line"><span>1</span></span></code></pre></div><p>如果输出结果大于 0，就意味着您的硬件支持虚拟化。重启，进入 BIOS 设置中启用 VT 技术。</p><p>现在使用下面的命令安装 <code>kvm-ok</code> 实用程序，该程序用于确定您的服务器是否能够运行硬件加速的 KVM 虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo apt install cpu-checker</span></span></code></pre></div><p>运行 kvm-ok 命令确认输出结果，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo kvm-ok</span></span>
<span class="line"><span>INFO: /dev/kvm exists</span></span>
<span class="line"><span>KVM acceleration can be used</span></span></code></pre></div><h3 id="第二步-安装-kvm-及其依赖包" tabindex="-1">第二步：安装 KVM 及其依赖包 <a class="header-anchor" href="#第二步-安装-kvm-及其依赖包" aria-label="Permalink to “第二步：安装 KVM 及其依赖包”">​</a></h3><p>运行下面的 apt 命令安装 KVM 及其依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo apt update</span></span>
<span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo apt install qemu qemu-kvm libvirt-bin  bridge-utils  virt-manager</span></span></code></pre></div><p>只要上图相应的软件包安装成功，那么你的本地用户（对于我来说是 <code>linuxtechi</code>）将被自动添加到 <code>libvirtd</code> 群组。</p><h3 id="第三步-启动并启用-libvirtd-服务" tabindex="-1">第三步：启动并启用 libvirtd 服务 <a class="header-anchor" href="#第三步-启动并启用-libvirtd-服务" aria-label="Permalink to “第三步：启动并启用 libvirtd 服务”">​</a></h3><p>我们在 Ubuntu 18.04 服务器上安装 qemu 和 libvirtd 软件包之后，它就会自动启动并启用 <code>libvirtd</code> 服务，如果 <code>libvirtd</code> 服务没有开启，则运行以下命令开启，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo service libvirtd start</span></span>
<span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo update-rc.d libvirtd enable</span></span></code></pre></div><p>现在使用下面的命令确认 libvirtd 服务的状态，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ service libvirtd status</span></span></code></pre></div><p>输出结果如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/libvirtd-command-ubuntu18-04.jpg" alt=""></p><h3 id="第四步-为-kvm-虚拟机配置桥接网络" tabindex="-1">第四步：为 KVM 虚拟机配置桥接网络 <a class="header-anchor" href="#第四步-为-kvm-虚拟机配置桥接网络" aria-label="Permalink to “第四步：为 KVM 虚拟机配置桥接网络”">​</a></h3><p>只有通过桥接网络，KVM 虚拟机才能访问外部的 KVM 管理程序或主机。在Ubuntu 18.04中，网络由 <code>netplan</code> 实用程序管理，每当我们新安装一个 Ubuntu 18.04 系统时，会自动创建一个名称为 <code>/etc/netplan/50-cloud-init.yaml</code> 文件，其配置了静态 IP 和桥接网络，<code>netplan</code> 实用工具将引用这个文件。</p><p>截至目前，我已经在此文件配置了静态 IP，文件的具体内容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>  ethernets:</span></span>
<span class="line"><span>    ens33:</span></span>
<span class="line"><span>      addresses: [192.168.0.51/24]</span></span>
<span class="line"><span>      gateway4: 192.168.0.1</span></span>
<span class="line"><span>      nameservers:</span></span>
<span class="line"><span>        addresses: [192.168.0.1]</span></span>
<span class="line"><span>      dhcp4: no</span></span>
<span class="line"><span>      optional: true</span></span>
<span class="line"><span>  version: 2</span></span></code></pre></div><p>我们在这个文件中添加桥接网络的配置信息，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo vi /etc/netplan/50-cloud-init.yaml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>network:</span></span>
<span class="line"><span>  version: 2</span></span>
<span class="line"><span>  ethernets:</span></span>
<span class="line"><span>    ens33:</span></span>
<span class="line"><span>      dhcp4: no</span></span>
<span class="line"><span>      dhcp6: no</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  bridges:</span></span>
<span class="line"><span>    br0:</span></span>
<span class="line"><span>      interfaces: [ens33]</span></span>
<span class="line"><span>      dhcp4: no</span></span>
<span class="line"><span>      addresses: [192.168.0.51/24]</span></span>
<span class="line"><span>      gateway4: 192.168.0.1</span></span>
<span class="line"><span>      nameservers:</span></span>
<span class="line"><span>        addresses: [192.168.0.1]</span></span></code></pre></div><p>正如你所看到的，我们已经从接口（<code>ens33</code>）中删除了 IP 地址，并将该 IP 添加到 <code>br0</code> 中，并且还将接口（<code>ens33</code>）添加到 <code>br0</code>。使用下面的 <code>netplan</code> 命令使更改生效，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo netplan apply</span></span></code></pre></div><p>如果您想查看 debug 日志请使用以下命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo netplan --debug  apply</span></span></code></pre></div><p>现在使用以下方法确认网络桥接状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo networkctl status -a</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/networkctl-command-output-ubuntu18-04.jpg" alt=""></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ ifconfig</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/ifconfig-command-output-ubuntu18-04.jpg" alt=""></p><h3 id="第五步-创建虚拟机-使用-virt-manager-或-virt-install-命令" tabindex="-1">第五步：创建虚拟机（使用 virt-manager 或 virt-install 命令） <a class="header-anchor" href="#第五步-创建虚拟机-使用-virt-manager-或-virt-install-命令" aria-label="Permalink to “第五步：创建虚拟机（使用 virt-manager 或 virt-install 命令）”">​</a></h3><p>有两种方式创建虚拟机：</p><ul><li><code>virt-manager</code>（图形化工具）</li><li><code>virt-install</code>（命令行工具）</li></ul><h4 id="使用-virt-manager-创建虚拟机" tabindex="-1">使用 virt-manager 创建虚拟机 <a class="header-anchor" href="#使用-virt-manager-创建虚拟机" aria-label="Permalink to “使用 virt-manager 创建虚拟机”">​</a></h4><p>通过执行下面的命令启动 <code>virt-manager</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo virt-manager</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/Start-Virt-Manager-Ubuntu18-04.jpg" alt=""></p><p>创建一个新的虚拟机：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/ISO-file-Virt-Manager.jpg" alt=""></p><p>点击“下一步”然后选择 ISO 镜像文件，我使用的是 RHEL 7.3 iso 镜像。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/Select-ISO-file-virt-manager-Ubuntu18-04-Server.jpg" alt=""></p><p>点击“下一步”。</p><p>在接下来的几个窗口中，系统会提示要求您为 VM 分配内存，处理器数量和磁盘空间。</p><p>并指定虚拟机名字和桥接网络名：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/VM-Name-Network-Virt-Manager-Ubuntu18-04.jpg" alt=""></p><p>点击“结束”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/05/RHEL7-3-Installation-Virt-Manager.jpg" alt=""></p><p>接下来只需要按照屏幕指示安装系统。</p><h4 id="使用virt-install命令从命令行界面创建虚拟机" tabindex="-1">使用virt-install命令从命令行界面创建虚拟机 <a class="header-anchor" href="#使用virt-install命令从命令行界面创建虚拟机" aria-label="Permalink to “使用virt-install命令从命令行界面创建虚拟机”">​</a></h4><p>使用下面的 <code>virt-install</code> 命令从终端创建一个虚拟机，它将在命令行界面中开始安装，并根据您对虚拟机的名字，说明，ISO 文件位置和桥接配置的设置创建虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>linuxtechi@kvm-ubuntu18-04:~$ sudo virt-install  -n DB-Server  --description &quot;Test VM for Database&quot;  --os-type=Linux  --os-variant=rhel7  --ram=1096  --vcpus=1  --disk path=/var/lib/libvirt/images/dbserver.img,bus=virtio,size=10  --network bridge:br0 --graphics none  --location /home/linuxtechi/rhel-server-7.3-x86_64-dvd.iso --extra-args console=ttyS0</span></span></code></pre></div><p>本文到此为止，我希望这篇文章能帮助你能够在 Ubuntu 18.04 服务器上成功安装 KVM。 除此之外，KVM 也是 Openstack 默认的管理程序。</p>`,60)),t("p",null,[s[1]||(s[1]=a("阅读更多：“",-1)),i(n,{href:"https://www.linuxtechi.com/create-revert-delete-kvm-virtual-machine-snapshot-virsh-command/"},{default:e(()=>[...s[0]||(s[0]=[t("strong",null,"如何使用 virsh 命令创建，还原和删除 KVM 虚拟机快照",-1)])]),_:1}),s[2]||(s[2]=a("”",-1))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[4]||(s[4]=a("via: ",-1)),i(n,{href:"https://www.linuxtechi.com/install-configure-kvm-ubuntu-18-04-server/"},{default:e(()=>[...s[3]||(s[3]=[a("https://www.linuxtechi.com/install-configure-kvm-ubuntu-18-04-server/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=a("作者：",-1)),i(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...s[5]||(s[5]=[a("Pradeep Kumar",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),i(n,{href:"https://github.com/wyxplus"},{default:e(()=>[...s[7]||(s[7]=[a("wyxplus",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const w=l(u,[["render",c]]);export{x as __pageData,w as default};
